mapper.select:
SELECT 
  FROM (
        SELECT apr15_repr_corp.*
             , f_cdnm('ReprCorpType', apr15_corp_type, apr15_company_id, f_today()) AS apr15_corp_type_nm
             , apr10_stamp_nm                                                       AS apr15_stamp_nm
          FROM apr15_repr_corp
               LEFT JOIN apr10_stamp ON apr10_stamp_id = apr15_stamp_id
         WHERE apr15_company_id = #{companyId}
           AND apr15_repr_corp_id = #{reprCorpId}
       ) t

mapper.update:
UPDATE apr15_repr_corp
   SET apr15_corp_type   = #{r.corpType},
       apr15_corp_nm     = #{r.corpName},
       apr15_repr_nm     = #{r.reprName},
       apr15_corp_reg_yn = #{r.corpRegYn},
       apr15_stamp_id    = #{r.stampId},
       apr15_note        = #{r.note},
       apr15_use_yn      = #{r.useYn}
 WHERE apr15_repr_corp_id = #{r.reprCorpId}
   AND apr15_company_id   = #{companyId}

mapper.delete:
DELETE FROM apr15_repr_corp
 WHERE apr15_repr_corp_id = #{reprCorpId}
   AND apr15_company_id   = #{companyId}

mapper.select:
SELECT COUNT(*)
  FROM apr16_stamp_doc
 WHERE apr16_repr_corp_id = #{reprCorpId}
